import{_ as t,o as h,c,a2 as i}from"./chunks/framework.62rcL0wY.js";const u=JSON.parse('{"title":"Cài đặt và chạy lần đầu","description":"","frontmatter":{},"headers":[],"relativePath":"bat-dau/cai-dat.md","filePath":"bat-dau/cai-dat.md"}'),a={name:"bat-dau/cai-dat.md"};function o(e,n,r,g,d,l){return h(),c("div",null,[...n[0]||(n[0]=[i('<h1 id="cai-dat-va-chay-lan-dau" tabindex="-1">Cài đặt và chạy lần đầu <a class="header-anchor" href="#cai-dat-va-chay-lan-dau" aria-label="Permalink to &quot;Cài đặt và chạy lần đầu&quot;">​</a></h1><p>Trang này hướng dẫn cách tải bản Clickermann v4.13 chính thức, mở cửa sổ chính lần đầu và làm quen với các thư mục quan trọng nhất.</p><h2 id="cac-buoc-mo-cua-so-chinh-lan-dau" tabindex="-1">Các bước mở cửa sổ chính lần đầu <a class="header-anchor" href="#cac-buoc-mo-cua-so-chinh-lan-dau" aria-label="Permalink to &quot;Các bước mở cửa sổ chính lần đầu&quot;">​</a></h2><p>Clickermann là phần mềm miễn phí (<strong>FREEWARE</strong>) chạy trên Windows, được phân phối nguyên trạng và không đi kèm mã nguồn. Bản chính thức duy nhất được tải từ trang chủ của tác giả:</p><ol><li><strong>Tải chương trình:</strong> Truy cập trang chủ chính thức <a href="http://crapware.aidf.org" target="_blank" rel="noreferrer">http://crapware.aidf.org</a> để tải bản Clickermann v4.13 (tài liệu này <strong>không đính kèm tệp <code>.exe</code></strong>, và bạn không nên mua bán chương trình dưới mọi hình thức).</li><li><strong>Giải nén:</strong> Trang chủ có hai tệp nén là <code>cm413_32.zip</code> (32-bit) và <code>cm413_64.zip</code> (64-bit). Giải nén một tệp ra thư mục riêng trên máy. Help không hướng dẫn nên chọn bản nào.</li><li><strong>Mở chương trình:</strong> Trong thư mục vừa giải nén, chạy tệp <code>Clickermann.exe</code>.</li><li><strong>Kiểm tra:</strong> Cửa sổ chính của Clickermann xuất hiện. Bước này chưa được chạy thử trên Windows.</li></ol><p>Tên tệp ở các bước trên lấy từ hai tệp nén tải về trang chủ ngày 31/10/2026, không phải từ help.</p><div class="info custom-block"><p class="custom-block-title">Hình minh họa sẽ bổ sung</p><p>Hình chụp thư mục chương trình Clickermann v4.13 trên Windows (gồm bản 32-bit, 64-bit và các thư mục con) sẽ được bổ sung sau khi chụp trực tiếp trên máy Windows.</p></div><h2 id="ba-thanh-phan-can-biet-khi-moi-dung" tabindex="-1">Ba thành phần cần biết khi mới dùng <a class="header-anchor" href="#ba-thanh-phan-can-biet-khi-moi-dung" aria-label="Permalink to &quot;Ba thành phần cần biết khi mới dùng&quot;">​</a></h2><p>Khi làm việc hằng ngày với Clickermann, bạn chỉ cần quan tâm tới 3 nơi sau:</p><ul><li><strong>Tệp chạy chính (<code>.exe</code>):</strong> Nằm trong thư mục chương trình (<code>%Clickermann%</code>), dùng để khởi động Clickermann.</li><li><strong>Thư mục <code>data/</code> (và tệp <code>data/const.txt</code>):</strong> Chứa các tệp dữ liệu của chương trình, quan trọng nhất là tệp <code>data/const.txt</code> định nghĩa các hằng số nạp lúc khởi động (như mã phím <code>#SPACE</code>, <code>#ENTER</code>, <code>#TRUE</code>, <code>#FALSE</code>...). Bạn có thể chỉnh sửa <code>data/const.txt</code>, nhưng hãy nhớ sao lưu lại khi tải phiên bản mới.</li><li><strong>Thư mục dự án:</strong> Là thư mục chứa tệp script <code>.cms</code> mà bạn đang mở. Từ bản v4.6.000, mọi đường dẫn tương đối trong script (như tệp ảnh <code>.bmp</code>, tệp <code>.txt</code>, <code>.ini</code>) đều được tính từ thư mục chứa tệp script đang nạp. Vì vậy, bạn nên tạo một thư mục riêng cho mỗi bài thực hành và lưu tệp <code>.cms</code> vào đó.</li></ul><h2 id="luu-y-khi-khoi-chay-lan-dau" tabindex="-1">Lưu ý khi khởi chạy lần đầu <a class="header-anchor" href="#luu-y-khi-khoi-chay-lan-dau" aria-label="Permalink to &quot;Lưu ý khi khởi chạy lần đầu&quot;">​</a></h2><h3 id="kiem-tra-cap-nhat-qua-mang-khi-khoi-dong" tabindex="-1">Kiểm tra cập nhật qua mạng khi khởi động <a class="header-anchor" href="#kiem-tra-cap-nhat-qua-mang-khi-khoi-dong" aria-label="Permalink to &quot;Kiểm tra cập nhật qua mạng khi khởi động&quot;">​</a></h3><p>Mỗi khi khởi động, Clickermann sẽ <strong>tự động kết nối mạng để kiểm tra phiên bản mới</strong> trên máy chủ của tác giả. Nếu tường lửa (Firewall) có hỏi hoặc báo hoạt động mạng lúc vừa mở chương trình thì đây là hành vi bình thường.</p><p>Nếu không muốn chương trình tự kết nối mạng khi mở, bạn có thể <strong>tắt tính năng tự động kiểm tra cập nhật trong phần cài đặt</strong> của chương trình.</p><h3 id="canh-bao-tu-phan-mem-diet-virus" tabindex="-1">Cảnh báo từ phần mềm diệt virus <a class="header-anchor" href="#canh-bao-tu-phan-mem-diet-virus" aria-label="Permalink to &quot;Cảnh báo từ phần mềm diệt virus&quot;">​</a></h3><p>Một số phần mềm diệt virus (thường là các trình diệt virus ít tên tuổi, không phổ biến) có thể cảnh báo vì chương trình có khả năng theo dõi, mô phỏng chuột và bàn phím. Help khuyên thêm Clickermann vào danh sách loại trừ (exclusion) của trình diệt virus. Trước khi làm vậy, bạn nên biết tệp <code>.exe</code> tải về không có chữ ký số và trang chủ chỉ dùng HTTP, nên khó tự xác minh tệp còn nguyên vẹn. Nếu lo ngại, hãy chạy trong máy ảo và không tắt bảo vệ trên máy chính.</p><h2 id="chi-tiet-them-ve-cac-tep-khac-trong-thu-muc-chuong-trinh" tabindex="-1">Chi tiết thêm về các tệp khác trong thư mục chương trình <a class="header-anchor" href="#chi-tiet-them-ve-cac-tep-khac-trong-thu-muc-chuong-trinh" aria-label="Permalink to &quot;Chi tiết thêm về các tệp khác trong thư mục chương trình&quot;">​</a></h2><p>Các tệp và thư mục dưới đây ít khi cần chạm tới khi mới bắt đầu:</p><ul><li><strong><code>data/default.txt</code>:</strong> Tệp đặt kịch bản mặc định (hỗ trợ từ v4.13.014; Suy luận: dùng làm mẫu khi tạo script mới).</li><li><strong><code>data/lang/...</code>:</strong> Chứa thư mục mẫu code (<code>data/lang/ru/templates/</code>) và tệp cấu hình menu chèn lệnh nhanh (<code>data/lang/ru/qinsert_menu.txt</code>, có thể thay <code>ru</code> bằng ngôn ngữ khác).</li><li><strong><code>plugins/</code> (🟠 Chưa thống nhất):</strong><ul><li><strong>Nên làm:</strong> Khi dùng plugin mở rộng (<code>.dll</code>), hãy ưu tiên đặt tệp <code>.dll</code> trong thư mục <code>%Clickermann%/plugins/</code> hoặc đặt ngay cùng thư mục với tệp script <code>.cms</code>.</li></ul><details class="details custom-block"><summary>Vì sao chưa chắc</summary><p>Trang lệnh <a href="/clickermann-guide-vi/lenh/kich-ban.html#call"><code>CALL</code></a> trong help nhắc tới thư mục <code>%Clickermann%/plugins</code>, trong khi bài viết <a href="/clickermann-guide-vi/khai-niem/plugin.html">Plugin</a> trong help lại ghi tệp DLL đặt trong thư mục dự án (cạnh script đang chạy hoặc trong thư mục con). Xem thêm tại <a href="/clickermann-guide-vi/phu-luc/can-kiem-tra-tren-windows.html#thu-muc-nap-plugin-dll-cua-call">Cần kiểm tra trên Windows</a>.</p></details></li><li><strong><code>config.ini</code>:</strong> Tệp cấu hình của chương trình. Lịch sử phiên bản (v4.11.000) ghi cài đặt phím tắt mới không tương thích với <code>config.ini</code> cũ, và phần mô tả lệnh <a href="/clickermann-guide-vi/lenh/winapi.html#getmessage"><code>GETMESSAGE</code></a> có nhắc tới việc bật tham số <code>msg_hook</code> trong <code>config.ini</code>.</li></ul><hr><p><strong>Bước tiếp theo:</strong> Sau khi mở được chương trình, hãy chuyển sang bài <a href="/clickermann-guide-vi/bat-dau/man-hinh-chinh.html">Màn hình chính</a> để làm quen với các nút điều khiển và phím tắt.</p><p><em>Nguồn: Tài liệu trợ giúp <code>help.chm</code> (phần Thông tin chương trình, Giới thiệu ngôn ngữ, Trình soạn thảo, FAQ và Lịch sử phiên bản).</em></p>',22)])])}const s=t(a,[["render",o]]);export{u as __pageData,s as default};
